			break
		}

		history = append(history, anthropic.NewUserMessage(anthropic.NewTextBlock(query)))
		var err error
		history, err = agentLoop(context.Background(), client, history)
		if err != nil {
			fmt.Fprintf(os.Stderr, "agent loop: %v\n", err)
			continue
